// Human labels for scripts and languages, generated by the harvester
// (to_dataset.py write_label_maps) from gflanguages, so the frontend renders
// readable names without shipping gftools. See the language-support task.
import languagesRaw from "@/data/languages.json";
import scriptsRaw from "@/data/scripts.json";
import vendorsRaw from "@/data/vendors.json";

export interface LanguageMeta {
  name: string;
  script: string;
  population: number;
  region: string;
}

// Continent buckets in the order Google Fonts lists them; "Other" (languages
// with no CLDR region) trails at the end when present.
export const LANGUAGE_REGIONS = [
  "Africa",
  "Americas",
  "Asia",
  "Europe",
  "Oceania",
  "Other",
] as const;

const scripts = scriptsRaw as Record<string, string>;
const languages = languagesRaw as Record<string, LanguageMeta>;
// OS/2 achVendID -> foundry name, from Microsoft's vendor registry
// (scripts/gen-vendors-data.mjs). Keyed by the uppercased 4-char code.
const vendors = vendorsRaw as Record<string, string>;

/** "Latn" -> "Latin"; unknown codes pass through unchanged. */
export function scriptLabel(code: string): string {
  return scripts[code] ?? code;
}

/** "en_Latn" -> "English"; unknown ids pass through unchanged. */
export function languageLabel(id: string): string {
  return languages[id]?.name ?? id;
}

/** "PYRS" -> "PYRS Fontlab"; codes with no registered foundry return the code
 *  itself, so the pill still shows something meaningful. */
export function vendorLabel(code: string): string {
  return vendors[code] ?? code;
}

export function languagePopulation(id: string): number {
  return languages[id]?.population ?? 0;
}

export function languageRegion(id: string): string {
  return languages[id]?.region ?? "Other";
}

/** Bucket items by the continent of their language id, preserving input order
 *  within each region and returning regions in LANGUAGE_REGIONS order. Empty
 *  regions are dropped. The shared core behind the two public groupers below. */
function bucketByRegion<T>(
  items: T[],
  idOf: (item: T) => string
): { region: string; items: T[] }[] {
  const byRegion = new Map<string, T[]>();
  for (const item of items) {
    const r = languageRegion(idOf(item));
    const bucket = byRegion.get(r);
    if (bucket) bucket.push(item);
    else byRegion.set(r, [item]);
  }
  return LANGUAGE_REGIONS.filter((r) => byRegion.has(r)).map((region) => ({
    region,
    items: byRegion.get(region) as T[],
  }));
}

/** Bucket lang ids by continent, each name-sorted, in LANGUAGE_REGIONS order.
 *  Only non-empty regions are returned. */
export function groupLanguagesByRegion(
  ids: string[]
): { region: string; ids: string[] }[] {
  const byName = (a: string, b: string) =>
    languageLabel(a).localeCompare(languageLabel(b));
  return bucketByRegion(ids, (id) => id).map(({ region, items }) => ({
    region,
    ids: [...items].sort(byName),
  }));
}

export interface LanguageRegionGroup {
  region: string;
  items: [string, number][];
  /** The region's `topN` most-spoken languages, which render up front. */
  topNSet: Set<string>;
}

/**
 * Bucket [langId, fontCount] pairs by continent for the filter sidebar,
 * preserving the incoming order within each region. Empty regions are dropped.
 *
 * `topNSet` always ranks by speaker population, never by the incoming order, so
 * flipping the panel to A–Z reorders pills without changing which ones hide.
 */
export function groupLanguageCountsByRegion(
  items: [string, number][],
  topN: number
): LanguageRegionGroup[] {
  return bucketByRegion(items, ([id]) => id).map(
    ({ region, items: regionItems }) => {
      const top = [...regionItems]
        .sort((a, b) => languagePopulation(b[0]) - languagePopulation(a[0]))
        .slice(0, topN);
      return {
        region,
        items: regionItems,
        topNSet: new Set(top.map(([id]) => id)),
      };
    }
  );
}

// Script -> total speaker population, summed from every language written in
// it (gflanguages), so Writing system pills can rank by real-world reach
// instead of how many fonts happen to declare that subset.
const SCRIPT_POPULATION: Record<string, number> = {};
for (const meta of Object.values(languages)) {
  if (!meta.script) continue;
  SCRIPT_POPULATION[meta.script] =
    (SCRIPT_POPULATION[meta.script] ?? 0) + (meta.population ?? 0);
}

export function scriptPopulation(code: string): number {
  return SCRIPT_POPULATION[code] ?? 0;
}
